// Follow-up corrections in compiled Rust/Win32 sources, preserving approved colour.
use std::{env,fs,path::{Path,PathBuf}};
mod previous { include!("build_v1383_followup_preferences.rs");pub fn run(){main();} }
fn exact(s:&mut String,old:&str,new:&str,n:usize,id:&str){assert_eq!(s.matches(old).count(),n,"follow-up {id}: expected {n} native anchors");*s=s.replace(old,new);assert!(s.contains(new),"follow-up {id}: compiled change missing");}
fn part(s:&mut String,start:&str,end:&str,old:&str,new:&str,n:usize,id:&str){assert_eq!(s.matches(start).count(),1,"follow-up {id}: function ambiguous");let a=s.find(start).unwrap();let b=a+s[a..].find(end).expect("function end");let mut t=s[a..b].to_owned();exact(&mut t,old,new,n,id);s.replace_range(a..b,&t);}
fn edit(out:&Path,name:&str,f:impl FnOnce(&mut String)){let p=out.join(name);let mut s=fs::read_to_string(&p).expect("read generated Rust");f(&mut s);fs::write(p,s).expect("write generated Rust");}
