exact(s,"let r = reference_tab_rect(index as i32);","let r = audit_tab_rect(state,index as i32);",1,"R01 paint geometry");
part(s,"unsafe fn paint_mode_tab(","unsafe fn dps_row_layout_responsive(","bottom: y + 24,","bottom: y + 34,",1,"R01 tab bottom");
