part(s,"unsafe fn dps_row_layout_responsive(","unsafe fn paint_dps_secondary_colored(","else if show_imagines && has_class && spare_after_class >= badge_w + badge_outer_gap + dps_adaptive_logical_px(48, scale) { 1 }","else if show_imagines && _row.imagines.len()==1 && has_class && spare_after_class >= badge_w + badge_outer_gap + dps_adaptive_logical_px(48, scale) { 1 }",1,"R10 no misleading single of two badges");
