exact(s,"fn normal_meter_fs_width(scale:i32)->i32{dps_adaptive_logical_px(38,scale).max(30)}","fn normal_meter_fs_width(scale:i32)->i32{dps_adaptive_logical_px(38,scale).max(38)}",1,"R12 F/S reserve");
exact(s,"let secondary = dps_secondary_compact_measured(hdc, row,","let secondary = audit_shared_secondary(hdc, row,",1,"R11 consistent metadata normal");
exact(s,"let text = dps_secondary_compact_measured(hdc, row, detail.right - detail.left);","let text = audit_shared_secondary(hdc, row, detail.right - detail.left);",1,"R11 consistent metadata Raid");
exact(s,"let max_width=(rc.right-8).clamp(160,420);","let max_width=(rc.right-8).clamp(160,280);",1,"R13 bounded tooltip");
exact(s,"let cards_top=identity.bottom+7;let cards_bottom=(detail_tab_top()-74).max(cards_top+70);","let cards_top=identity.bottom+7;let cards_bottom=(detail_tab_top()-62).max(cards_top+86);",1,"R16 card bottom");
